{"command":"@'
import envparse

# 1. Key ordering and last occurrence wins
res = envparse.parse_env("A=1\nB=2\nC=3\nB=4\nA=5")
assert list(res.keys()) == ["A", "B", "C"], f"Expected ['A', 'B', 'C'], got {list(res.keys())}"
assert res == {"A": "5", "B": "4", "C": "3"}

# 2. CRLF handling
res_crlf = envparse.parse_env("A=1\r\nB=2\r\nC=3\r\n")
assert res_crlf == {"A": "1", "B": "2", "C": "3"}

# 3. Escape sequences in double quotes
# \n, \t, \r, \", \\
res_escapes = envparse.parse_env('TEST="\\n\\t\\r\\"\\\\\\z\\1"')
expected = "\n\t\r\"\\\z\\1"
assert res_escapes["TEST"] == expected, f"Expected {repr(expected)}, got {repr(res_escapes['TEST'])}"

# Escaped backslash followed by n
res_slash_n = envparse.parse_env('TEST="\\\\n"')
assert res_slash_n["TEST"] == "\\n", f"Expected '\\n', got {repr(res_slash_n['TEST'])}"

# Empty quotes
assert envparse.parse_env('A=""') == {"A": ""}
assert envparse.parse_env("A=''") == {"A": ""}

# Single quotes literal
assert envparse.parse_env("A='\\n\\t\\r\\\"\\\\\\z'") == {"A": "\\n\\t\\r\\\"\\\\\\z"}

# 4. Comments and unquoted values
assert envparse.parse_env("A=foo # bar # baz") == {"A": "foo"}
assert envparse.parse_env("A=foo#bar#baz") == {"A": "foo#bar#baz"}
assert envparse.parse_env("A= # comment") == {"A": ""}
assert envparse.parse_env("A=#notcomment") == {"A": "#notcomment"}
assert envparse.parse_env("A=   ") == {"A": ""}
assert envparse.parse_env("A=") == {"A": ""}
assert envparse.parse_env("A=foo 'bar # baz' # comment") == {"A": "foo 'bar # baz'"}

# 5. Export prefix
assert envparse.parse_env("export FOO=1") == {"FOO": "1"}
assert envparse.parse_env("export   FOO=1") == {"FOO": "1"}
assert envparse.parse_env("export\tFOO=1") == {"FOO": "1"}
assert envparse.parse_env("  export   FOO  =1") == {"FOO": "1"}
assert envparse.parse_env("export=1") == {"export": "1"}
assert envparse.parse_env("export_FOO=1") == {"export_FOO": "1"}

# 6. Error handling and line numbering
try:
    envparse.parse_env("export =1")
    assert False
except ValueError as e:
    assert str(e) == "invalid line 1: export =1", f"Got {e}"

try:
    envparse.parse_env("# c\n\n\r\nexport =1")
